{
  "$schema": "https://opencode.ai/config.json",

  // Полный автономный режим: никаких запросов на подтверждение.
  // bash / edit / external_directory / /tmp — всё разрешено без вопросов.
  // Если нужно вернуть точечные подтверждения — замени на объект:
  //   "permission": { "bash": { "rm *": "ask", "*": "allow" }, "external_directory": "ask" }
  "permission": "allow",

  "snapshot": true,
  "autoupdate": true,
  "share": "disabled",

  "compaction": { "auto": true, "tail_turns": 20 },
  "tool_output": { "max_lines": 400, "max_bytes": 32768 }
}

